#include <iostream>
#include <string>
#include <memory>

class Employee {
public:
    Employee(std::string first, std::string last, std::string ssn)
        : firstName(std::move(first)), lastName(std::move(last)), socialSecurityNumber(std::move(ssn)) {}

    virtual ~Employee() = default;

    void setFirstName(const std::string& first) { firstName = first; }
    std::string getFirstName() const { return firstName; }

    void setLastName(const std::string& last) { lastName = last; }
    std::string getLastName() const { return lastName; }

    void setSocialSecurityNumber(const std::string& ssn) { socialSecurityNumber = ssn; }
    std::string getSocialSecurityNumber() const { return socialSecurityNumber; }

    virtual double earnings() const = 0;

    virtual void print() const {
        std::cout << getFirstName() << ' ' << getLastName()
                  << "\nsocial security number: " << getSocialSecurityNumber();
    }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
};

class MockEmployee : public Employee {
public:
    MockEmployee(std::string first, std::string last, std::string ssn, double pay)
        : Employee(std::move(first), std::move(last), std::move(ssn)), fixedPay(pay) {}

    double earnings() const override {
        return fixedPay;
    }

    void print() const override {
        std::cout << "mock employee: ";
        Employee::print();
        std::cout << "\nearnings: " << earnings();
    }

private:
    double fixedPay{0.0};
};

int main() {
    std::unique_ptr<Employee> emp = std::make_unique<MockEmployee>("John", "Smith", "111-11-1111", 800.0);
    emp->print();
    std::cout << std::endl;
    return 0;
}

#include <iostream>
#include <string>
#include <stdexcept>

class Employee {
public:
    Employee(std::string first, std::string last, std::string ssn)
        : firstName(std::move(first)), lastName(std::move(last)), socialSecurityNumber(std::move(ssn)) {}
    virtual ~Employee() = default;

    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }
    std::string getSocialSecurityNumber() const { return socialSecurityNumber; }

    virtual double earnings() const = 0;
    virtual void print() const {
        std::cout << getFirstName() << ' ' << getLastName()
                  << "\nsocial security number: " << getSocialSecurityNumber();
    }
private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
};

class SalariedEmployee : public Employee {
public:
    SalariedEmployee(const std::string& first, const std::string& last,
                     const std::string& ssn, double salary = 0.0)
        : Employee(first, last, ssn) {
        setWeeklySalary(salary);
    }

    void setWeeklySalary(double salary) {
        if (salary >= 0.0) {
            weeklySalary = salary;
        } else {
            throw std::invalid_argument("Weekly salary must be >= 0.0");
        }
    }

    double getWeeklySalary() const { return weeklySalary; }

    double earnings() const override {
        return getWeeklySalary();
    }

    void print() const override {
        std::cout << "salaried employee: ";
        Employee::print();
        std::cout << "\nweekly salary: " << getWeeklySalary();
    }

private:
    double weeklySalary{0.0};
};

int main() {
    SalariedEmployee salaried("Sue", "Jones", "222-22-2222", 600.0);
    std::cout << "Invoking earnings: " << salaried.earnings() << "\n\n";
    salaried.print();
    std::cout << std::endl;
    return 0;
}
